fn is_palindrome(text: Vec<char>) -> bool {
    // Helper function: ASCII uppercase to lowercase conversion,
    // leaves all other chars unchanged.
    fn ascii_to_lowercase(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Convert uppercase ASCII to lowercase ASCII by adding 32
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let len = text.len();
    if len <= 1 {
        return true; // empty or single character is palindrome
    }

    let mut left = 0;
    let mut right = len - 1;

    while left < right {
        let left_char = ascii_to_lowercase(text[left]);
        let right_char = ascii_to_lowercase(text[right]);

        if left_char != right_char {
            return false;
        }

        left += 1;
        if right == 0 { // Prevent underflow; should not happen if left < right
            break;
        }
        right -= 1;
    }

    true
}